CREATE TABLE COUNTRY (    COUNTRY_ID NUMBER PRIMARY KEY,    NAME VARCHAR2(100) NOT NULL);CREATE TABLE CATEGORY (    CATEGORY_ID NUMBER PRIMARY KEY,    CNAME VARCHAR2(100) NOT NULL);CREATE TABLE INGREDIENT (    INGREDIENT_ID NUMBER PRIMARY KEY,    INAME VARCHAR2(100) NOT NULL,    DESCRIPTION VARCHAR2(1000));CREATE TABLE APP_USER (    EMAIL VARCHAR2(150) PRIMARY KEY,    NAME VARCHAR2(100) NOT NULL,    LNAME VARCHAR2(100) NOT NULL);CREATE TABLE RECIPE (    RECIPE_ID NUMBER PRIMARY KEY,    RNAME VARCHAR2(255) NOT NULL,    INSTRUCTION VARCHAR2(4000) NOT NULL,    IMAGE_URL VARCHAR2(255),    VIDEO_URL VARCHAR2(255),    SOURCE_URL VARCHAR2(255),    CATEGORY_ID NUMBER,    COUNTRY_ID NUMBER,    CONSTRAINT FK_REC_CAT FOREIGN KEY (CATEGORY_ID) REFERENCES CATEGORY(CATEGORY_ID),    CONSTRAINT FK_REC_COU FOREIGN KEY (COUNTRY_ID) REFERENCES COUNTRY(COUNTRY_ID));CREATE TABLE RECIPE_INGREDIENTS (    RECIPE_ID NUMBER,    INGREDIENT_ID NUMBER,    MEASUREMENTS VARCHAR2(100),    PRIMARY KEY (RECIPE_ID, INGREDIENT_ID),    CONSTRAINT FK_RI_REC FOREIGN KEY (RECIPE_ID) REFERENCES RECIPE(RECIPE_ID),    CONSTRAINT FK_RI_ING FOREIGN KEY (INGREDIENT_ID) REFERENCES INGREDIENT(INGREDIENT_ID));CREATE TABLE USER_FAVORITES (    EMAIL VARCHAR2(150),    RECIPE_ID NUMBER,    PRIMARY KEY (EMAIL, RECIPE_ID),    CONSTRAINT FK_FAV_USR FOREIGN KEY (EMAIL) REFERENCES APP_USER(EMAIL),    CONSTRAINT FK_FAV_REC FOREIGN KEY (RECIPE_ID) REFERENCES RECIPE(RECIPE_ID));CREATE TABLE USERS_MODIFY (    EMAIL VARCHAR2(150),    RECIPE_ID NUMBER,    INGREDIENT_ID NUMBER,    MODIFICATION VARCHAR2(2000) NOT NULL,    PRIMARY KEY (EMAIL, RECIPE_ID, INGREDIENT_ID),    CONSTRAINT FK_MOD_USR FOREIGN KEY (EMAIL) REFERENCES APP_USER(EMAIL),    CONSTRAINT FK_MOD_REC FOREIGN KEY (RECIPE_ID) REFERENCES RECIPE(RECIPE_ID),    CONSTRAINT FK_MOD_ING FOREIGN KEY (INGREDIENT_ID) REFERENCES INGREDIENT(INGREDIENT_ID));Για τη σωστή απεικόνιση του διαγράμματος στο σχεσιακό μοντέλο, ακολουθήσαμε τα παρακάτω βήματα:Δημιουργία Πινάκων για τις Οντότητες: Κάθε οντότητα του διαγράμματος έγινε ένας πίνακας. Έτσι δημιουργήθηκαν οι πίνακες: RECIPE, INGREDIENT, CATEGORY, COUNTRY και APP_USER. Ως Primary Keys ορίσαμε τα υπογραμμισμένα πεδία (π.χ. RECIPE_ID, EMAIL), διασφαλίζοντας ότι κάθε εγγραφή είναι μοναδική.Συσχετίσεις 1:Ν (Foreign Keys): Για τις απλές συνδέσεις, όπως το ότι μια συνταγή ανήκει σε μία κατηγορία και μία χώρα, μεταφέραμε τα IDs των πινάκων CATEGORY και COUNTRY ως ξένα κλειδιά μέσα στον πίνακα RECIPE.Υλοποίηση Σχέσεων Μ:Ν (Πολλά-προς-Πολλά):Υλικά: Επειδή μια συνταγή έχει πολλά υλικά και το αντίστροφο, φτιάξαμε τον πίνακα RECIPE_INGREDIENTS. Εδώ χρησιμοποιήσαμε Σύνθετο Πρωτεύον Κλειδί (τον συνδυασμό RECIPE_ID και INGREDIENT_ID) αντί για κάποιο έξτρα ID, ώστε να μην έχουμε πλεονασμό.Αγαπημένα: Επειδή ένας χρήστης μπορεί να έχει πολλές αγαπημένες συνταγές, δεν βάλαμε πεδίο μέσα στον πίνακα του χρήστη, αλλά δημιουργήσαμε τον ξεχωριστό πίνακα USER_FAVORITES. Και εδώ το κλειδί είναι σύνθετο (EMAIL και RECIPE_ID).Τριμερής Σχέση (Τροποποιήσεις): Για τις προτάσεις των χρηστών, δημιουργήσαμε τον πίνακα USERS_MODIFY. 'Επειτα, ορίσαμε ως Πρωτεύον Κλειδί τον συνδυασμό των τριών ξένων κλειδιών: EMAIL, RECIPE_ID και INGREDIENT_ID.1. Πίνακας COUNTRYα) Not Null: Το πεδίο NAME πρέπει να είναι υποχρεωτικά συμπληρωμένο.β) Πρωτεύον Κλειδί: Το COUNTRY_ID προσδιορίζει μοναδικά κάθε χώρα.γ) Πεδίο Τιμών: Το COUNTRY_ID πρέπει να είναι θετικός αριθμός.2. Πίνακας CATEGORYα) Not Null: Το πεδίο CNAME είναι υποχρεωτικό.β) Πρωτεύον Κλειδί: Το CATEGORY_ID είναι το μοναδικό αναγνωριστικό της κατηγορίας.γ) Πεδίο Τιμών: Το CATEGORY_ID πρέπει να είναι θετικός αριθμός.3. Πίνακας INGREDIENTα) Not Null: Το πεδίο INAME είναι υποχρεωτικό.β) Πρωτεύον Κλειδί: Το INGREDIENT_ID προσδιορίζει μοναδικά το υλικό.γ) Πεδίο Τιμών: Δεν υπάρχουν ειδικοί περιορισμοί πέρα από τον τύπο δεδομένων.4. Πίνακας APP_USERα) Not Null: Τα πεδία NAME και LNAME είναι υποχρεωτικά.β) Πρωτεύον Κλειδί: Το EMAIL αποτελεί το πρωτεύον κλειδί (μοναδικό για κάθε χρήστη).γ) Πεδίο Τιμών: Το EMAIL πρέπει να ακολουθεί το σωστό format.5. Πίνακας RECIPEα) Not Null: Τα πεδία RNAME και INSTRUCTION είναι υποχρεωτικά.β) Πρωτεύον Κλειδί: Το RECIPE_ID είναι το μοναδικό αναγνωριστικό της συνταγής.γ) Ξένα Κλειδιά: Το CATEGORY_ID αναφέρεται στον πίνακα CATEGORY και το COUNTRY_ID στον πίνακα COUNTRY.δ) Πεδίο Τιμών: Τα IDs πρέπει να είναι έγκυροι αριθμοί που υπάρχουν στους αντίστοιχους πίνακες.6. Πίνακας RECIPE_INGREDIENTSα) Not Null: Τα πεδία RECIPE_ID και INGREDIENT_ID είναι υποχρεωτικά (λόγω PK).β) Πρωτεύον Κλειδί: Ο συνδυασμός (RECIPE_ID, INGREDIENT_ID) αποτελεί το σύνθετο πρωτεύον κλειδί.γ) Ξένα Κλειδιά: Το RECIPE_ID αναφέρεται στον πίνακα RECIPE και το INGREDIENT_ID στον πίνακα INGREDIENT.δ) Πεδίο Τιμών: Το πεδίο MEASUREMENTS μπορεί να έχει μια προκαθορισμένη τιμή  αν δεν οριστεί ποσότητα.7. Πίνακας USER_FAVORITESα) Not Null: Και τα δύο πεδία (EMAIL, RECIPE_ID) είναι υποχρεωτικά.β) Πρωτεύον Κλειδί: Ο συνδυασμός (EMAIL, RECIPE_ID) είναι το σύνθετο πρωτεύον κλειδί.γ) Ξένα Κλειδιά: Το EMAIL αναφέρεται στον πίνακα APP_USER και το RECIPE_ID στον πίνακα RECIPE.δ) Πεδίο Τιμών: Διασφαλίζεται ότι ένας χρήστης δεν μπορεί να έχει την ίδια συνταγή στα αγαπημένα του πάνω από μία φορά.8. Πίνακας USERS_MODIFYα) Not Null: Τα πεδία EMAIL, RECIPE_ID, INGREDIENT_ID και MODIFICATION είναι όλα υποχρεωτικά.β) Πρωτεύον Κλειδί: Ο συνδυασμός (EMAIL, RECIPE_ID, INGREDIENT_ID) αποτελεί το σύνθετο πρωτεύον κλειδί.γ) Ξένα Κλειδιά: Αναφορές στους πίνακες APP_USER (EMAIL), RECIPE (RECIPE_ID) και INGREDIENT (INGREDIENT_ID).δ) Πεδίο Τιμών: Το πεδίο MODIFICATION πρέπει να έχει ελάχιστο μήκος χαρακτήρων για να είναι έγκυρη η πρόταση.